package main
import "fmt"
func main() {
	ch := make(chan int)
	go func() { // 'go' starts a goroutine, a lightweight thread
		sum := 0
		for i := 1; i <= 10; i += 2 { sum += i * i }
		ch <- sum // send the result over the channel
	}()
	fmt.Println(<-ch) // receive it: prints 165
}

const std = @import("std");

fn fib(n: u32) u32 {
    return if (n < 2) n else fib(n - 1) + fib(n - 2);
}

pub fn main() !void {
    const f10 = comptime fib(10); // evaluated while compiling
    std.debug.print("fib(10) = {d}\n", .{f10});
}

import Math;
// Adapted from the Carbon design overview
fn SmallestFactor(n: i32) -> (i32, bool) {
  let limit: i32 = Math.Sqrt(n) as i32;
  var i: i32 = 2;
  while (i <= limit) {
    if (n % i == 0) { return (i, false); }
    i += 1;
  }
  return (n, true);
}

