#include <stdio.h>
#define N 5                      /* the preprocessor replaces N with 5 */

int main(void) {
    int scores[N] = {72, 85, 90, 64, 78};   /* indexes run 0 to 4 */
    int sum = 0;
    for (int i = 0; i < N; i++)
        sum += scores[i];
    printf("sum=%d average=%.1f\n", sum, (double)sum / N);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
static int cmp_int(const void *x, const void *y) {
    int a = *(const int *)x, b = *(const int *)y;
    return (a > b) - (a < b);
}
int main(void) {
    int v[] = {42, 7, 19, 3};
    qsort(v, 4, sizeof v[0], cmp_int);   /* qsort calls back into cmp_int */
    for (int i = 0; i < 4; i++) printf("%d ", v[i]);   /* prints 3 7 19 42 */
    return 0;
}

