/* K&R-style definition: parameter types follow the name list.
   Valid in 1978 and in C89; an error in C23. */
int add(a, b)
int a, b;
{
    return a + b;
}

#include <stdio.h>

int add(int a, int b);            /* prototype: the parameter types are declared */

int main(void) {
    printf("%d\n", add(2, 3));    /* the compiler checks this call: prints 5 */
    return 0;
}

int add(int a, int b) { return a + b; }

#include <stdio.h>

constexpr int N = 5;                 /* C23: a true named constant */

int main(void) {
    int *p = nullptr;                /* C23: nullptr replaces NULL */
    bool ok = true;                  /* C23: bool is a keyword */
    auto total = 0;                  /* C23: the type is inferred */
    for (int i = 1; i <= N; i++) total += i;   // C99: // comments, int in for
    if (ok && !p) printf("%d\n", total);       // prints 15 (build with -std=c23)
    return 0;
}

#include <algorithm>
#include <cstdio>
#include <vector>

template <typename T>   // one definition, many types
T largest(const std::vector<T> &v) { return *std::max_element(v.begin(), v.end()); }

int main() {
    std::vector<int> nums{3, 9, 4};
    nums.push_back(11);
    std::printf("%d\n", largest(nums));   // 11
}

#include <cstdio>
#include <vector>

int main() {
    std::vector<int> v{1, 2, 3, 4};               // brace initialization
    auto square = [](int x) { return x * x; };    // lambda expression
    int total = 0;
    for (int x : v) total += square(x);           // range-based for
    std::printf("%d\n", total);                   // 30
}
